exercises.solution:
def to_int(text, default=0):
    try:
        return int(text)
    except ValueError:
        return default

n = int(input())
total = 0
bad = 0
for _ in range(n):
    try:
        total += int(input())
    except ValueError:
        bad += 1
print(f"합계: {total}")
print(f"잘못된 입력: {bad}개")
